<?php
session_start();
require '../../includes/conexao.php';
require '../../includes/verificar_sessao.php';
verificar_perfil('Secretaria');
$id_secretaria=$_SESSION['id_usuario'];$mensagem='';
if(isset($_GET['visualizar'],$_GET['id_msg'])){$id_msg=intval($_GET['id_msg']);$stmt=$conexao->prepare('UPDATE mensagem SET lida=1 WHERE id_mensagem=? AND destinatario=?');$stmt->bind_param('ii',$id_msg,$id_secretaria);$stmt->execute();$stmt->close();$stmt=$conexao->prepare('SELECT m.*,u.nome AS remetente_nome FROM mensagem m JOIN usuario u ON u.id_usuario=m.remetente WHERE m.id_mensagem=? AND m.destinatario=?');$stmt->bind_param('ii',$id_msg,$id_secretaria);$stmt->execute();$msg=$stmt->get_result()->fetch_assoc();$stmt->close();if($msg):?><!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Secretaria | Mensagem</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f4f7fb;color:#1f2937}main{max-width:1180px;margin:32px auto;padding:0 20px 40px}.panel{background:#fff;border-radius:18px;padding:22px;border:1px solid #e5ebf6;box-shadow:0 10px 22px rgba(15,23,42,.04)}.cabecalho{border-bottom:1px solid #edf2f9;padding-bottom:12px;margin-bottom:16px}.cabecalho p{margin:5px 0;color:#666}.conteudo{line-height:1.6}</style></head><body><?php include '../../includes/menu_secretaria.php';?><main><section class="panel"><div class="cabecalho"><p><strong>De:</strong> <?php echo htmlspecialchars($msg['remetente_nome']);?></p><p><strong>Assunto:</strong> <?php echo htmlspecialchars($msg['assunto']??'Sem assunto');?></p><p><strong>Data:</strong> <?php echo (new DateTime($msg['data_envio']))->format('d/m/Y H:i');?></p></div><div class="conteudo"><?php echo nl2br(htmlspecialchars($msg['conteudo']));?></div><p><a href="mensagens_secretaria.php">&lt; Voltar</a></p></section></main></body></html><?php endif;exit();}
if(isset($_POST['enviar_msg'])){$tipo_destino=$_POST['tipo_destino']??'';$destinatario=intval($_POST['destinatario']??0);$assunto=trim($_POST['assunto']??'');$conteudo=trim($_POST['conteudo']??'');$ids=[];
    if($tipo_destino==='usuario'&&$destinatario>0){$stmt=$conexao->prepare('SELECT id_usuario FROM usuario WHERE id_usuario=? AND ativo=1');$stmt->bind_param('i',$destinatario);$stmt->execute();if($row=$stmt->get_result()->fetch_assoc()){$ids[]=(int)$row['id_usuario'];}$stmt->close();}
    elseif($tipo_destino==='turma'&&$destinatario>0){$stmt=$conexao->prepare('SELECT m.id_aluno FROM matricula m JOIN usuario u ON u.id_usuario=m.id_aluno WHERE m.id_turma=? AND u.ativo=1');$stmt->bind_param('i',$destinatario);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$ids[]=(int)$row['id_aluno'];}$stmt->close();}
    if(!$ids||$assunto===''||$conteudo===''){$mensagem='<div style="background:#fee;color:#9d1c1c;padding:10px;border-radius:8px;margin-bottom:15px;">Selecione um destinatário e preencha assunto e mensagem.</div>';}else{$stmt=$conexao->prepare('INSERT INTO mensagem(remetente,destinatario,assunto,conteudo,data_envio,lida) VALUES(?,?,?,?,NOW(),0)');$conexao->begin_transaction();$ok=true;foreach(array_unique($ids) as $id_destino){$stmt->bind_param('iiss',$id_secretaria,$id_destino,$assunto,$conteudo);if(!$stmt->execute()){$ok=false;break;}}$stmt->close();if($ok){$conexao->commit();$mensagem='<div style="background:#eaf7ee;color:#1d6f3b;padding:10px;border-radius:8px;margin-bottom:15px;">Mensagem enviada com sucesso.</div>';}else{$conexao->rollback();$mensagem='<div style="background:#fee;color:#9d1c1c;padding:10px;border-radius:8px;margin-bottom:15px;">Não foi possível enviar a mensagem.</div>';}}}
$destinatarios=[];$sql="SELECT u.id_usuario AS id,u.nome,u.perfil,t.nome AS turma_nome FROM usuario u LEFT JOIN matricula m ON m.id_aluno=u.id_usuario LEFT JOIN turma t ON t.id_turma=m.id_turma WHERE u.ativo=1 ORDER BY u.nome";$result=$conexao->query($sql);while($row=$result->fetch_assoc()){$rotulo=$row['nome'].' - '.$row['perfil'];if($row['perfil']==='Aluno'&&$row['turma_nome']){$rotulo.=' - '.$row['turma_nome'];}$destinatarios[]=['id'=>(int)$row['id'],'tipo'=>'usuario','rotulo'=>$rotulo];}$result=$conexao->query('SELECT id_turma AS id,nome AS rotulo FROM turma ORDER BY nome');while($row=$result->fetch_assoc()){$destinatarios[]=['id'=>(int)$row['id'],'tipo'=>'turma','rotulo'=>$row['rotulo'].' - Turma'];}
$mensagens=[];$stmt=$conexao->prepare('SELECT m.*,u.nome AS remetente_nome FROM mensagem m JOIN usuario u ON u.id_usuario=m.remetente WHERE m.destinatario=? ORDER BY m.data_envio DESC');$stmt->bind_param('i',$id_secretaria);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$mensagens[]=$row;}$stmt->close();
?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Secretaria | Mensagens</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f3f6fb;color:#1f2937}main{max-width:1040px;margin:32px auto;padding:0 20px 40px}.topo{background:linear-gradient(135deg,#0d3d70,#1d8ec6);color:#fff;border-radius:18px;padding:26px 28px;margin-bottom:24px}.topo h1{margin:0;font-size:2rem}.panel{background:#fff;border-radius:18px;padding:22px;border:1px solid #e5ebf6;box-shadow:0 10px 22px rgba(15,23,42,.04);margin-bottom:22px}.panel h2{margin-top:0;color:#133b6d}.label{font-size:.78rem;font-weight:bold;color:#555;display:block;margin:12px 0 4px}.input,.textarea{width:100%;border:1px solid #dfe9f6;border-radius:8px;padding:9px 12px;font:inherit}.textarea{height:90px;resize:vertical}.resultados{border:1px solid #dfe9f6;border-radius:8px;margin-top:5px;max-height:220px;overflow:auto}.resultado{display:block;width:100%;text-align:left;border:0;background:#fff;padding:9px 12px;cursor:pointer}.resultado:hover{background:#edf3ff}.btn{background:#0d4a8f;color:#fff;border:0;border-radius:8px;padding:10px 22px;font-weight:bold;cursor:pointer;margin-top:14px}table{width:100%;border-collapse:collapse;font-size:.875rem}th,td{text-align:left;padding:11px 12px;border-bottom:1px solid #edf2f9}th{font-size:.75rem;color:#6b7280;text-transform:uppercase}.nao-lida{font-weight:bold}.assunto{color:#374151;text-decoration:none}.badge{padding:4px 10px;border-radius:999px;font-size:.75rem;font-weight:bold}.nova{background:#fee2e2;color:#991b1b}.lida{background:#eaf7ef;color:#157c3d}</style></head><body><?php include '../../includes/menu_secretaria.php';?><main><section class="topo"><h1>Mensagens</h1></section><section class="panel"><?php echo $mensagem;?><h2>Nova mensagem</h2><form method="POST"><label class="label">Destinatário</label><input id="busca-destinatario" class="input" placeholder="Digite o nome ou a turma" autocomplete="off"><div id="resultados" class="resultados"></div><input type="hidden" name="tipo_destino" id="tipo_destino"><input type="hidden" name="destinatario" id="destinatario"><div id="selecionado" style="margin-top:8px;color:#0d4a8f;font-weight:bold"></div><label class="label">Assunto</label><input class="input" name="assunto" required><label class="label">Mensagem</label><textarea class="textarea" name="conteudo" required></textarea><button class="btn" name="enviar_msg" value="1">Enviar mensagem</button></form></section><section class="panel"><h2>Caixa de entrada</h2><?php if($mensagens):?><table><thead><tr><th>Remetente</th><th>Assunto</th><th>Data</th><th>Situação</th></tr></thead><tbody><?php foreach($mensagens as $msg):?><tr class="<?php echo $msg['lida']?'':'nao-lida';?>"><td><?php echo htmlspecialchars($msg['remetente_nome']);?></td><td><a class="assunto" href="?visualizar=1&id_msg=<?php echo $msg['id_mensagem'];?>"><?php echo htmlspecialchars($msg['assunto']??'Sem assunto');?></a></td><td><?php echo (new DateTime($msg['data_envio']))->format('d/m/Y');?></td><td><span class="badge <?php echo $msg['lida']?'lida':'nova';?>"><?php echo $msg['lida']?'Lida':'Não lida';?></span></td></tr><?php endforeach;?></tbody></table><?php else:?><p style="color:#666">Nenhuma mensagem na caixa de entrada.</p><?php endif;?></section></main><script>
const destinatarios=<?php echo json_encode($destinatarios,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP);?>;const busca=document.getElementById('busca-destinatario'),lista=document.getElementById('resultados');function render(){const termo=busca.value.toLocaleLowerCase('pt-BR').trim();lista.innerHTML='';if(!termo)return;destinatarios.filter(item=>item.rotulo.toLocaleLowerCase('pt-BR').includes(termo)).slice(0,30).forEach(item=>{const botao=document.createElement('button');botao.type='button';botao.className='resultado';botao.textContent=item.rotulo;botao.onclick=()=>{document.getElementById('tipo_destino').value=item.tipo;document.getElementById('destinatario').value=item.id;document.getElementById('selecionado').textContent='Selecionado: '+item.rotulo;busca.value=item.rotulo;lista.innerHTML='';};lista.appendChild(botao);});}busca.addEventListener('input',render);
</script></body></html>
